use ulw_loop_core::cli_output::ULW_LOOP_HELP;
use ulw_loop_core::domain_types::{UlwLoopItem,UlwLoopPlan,UlwLoopSuccessCriterion};
use ulw_loop_core::quality_gate::validate_quality_gate;
use ulw_loop_core::status_next_actions::status_next_actions;
use ulw_loop_core::surface::UlwLoopToolkitSurface;
use serde_json::json;
#[test] fn missing_manual_qa_names_accepted_forms(){let e=validate_quality_gate(&json!({}),None).expect_err("invalid");assert!(e.message.contains("accepted input")&&e.message.contains("bare object")&&e.message.contains("top-level \"qualityGate\" key"));}
#[test] fn next_actions_mentions_attempt_dir(){let c=UlwLoopSuccessCriterion{id:"C001".into(),scenario:"works".into(),user_model:"happy".into(),expected_evidence:"proof".into(),essential:None,captured_evidence:Some("passed".into()),status:"pass".into(),captured_at:None,notes:None,artifacts:None};let g=UlwLoopItem{id:"G001".into(),title:"Goal".into(),objective:"Do".into(),status:"in_progress".into(),success_criteria:vec![c],attempt:1,created_at:"now".into(),updated_at:"now".into(),started_at:None,completed_at:None,failed_at:None,review_blocked_at:None,evidence:None,failure_reason:None,steering_status:None,superseded_by:None,supersedes:None,blocked_reason:None,blocker_signature:None,blocker_occurrence_count:None,required_external_decision:None,non_retriable:None,steering_evidence:None,steering_rationale:None};let p=UlwLoopPlan{version:1,revision:None,brief:None,ledger_reset_revision:None,evidence_layout_version:None,created_at:"now".into(),updated_at:"now".into(),brief_path:"b".into(),goals_path:"g".into(),ledger_path:"l".into(),codex_goal_mode:None,codex_objective:None,codex_objective_aliases:None,acknowledged_driver_objectives:None,aggregate_completion:None,active_goal_id:Some("G001".into()),validation_batches:None,goals:vec![g]};assert!(status_next_actions(&p,Some(UlwLoopToolkitSurface::OmoSenpi)).join("\n").contains("currentAttemptDir"));}
#[test] fn cli_help_mentions_attempt_dir(){assert!(ULW_LOOP_HELP.contains("currentAttemptDir"));}
